import{_ as e,o as a,c as l,a as r}from"./app.DkoUFz-u.js";const g=JSON.parse('{"title":"豆包学习笔记：从字节内孵化器到全球多模态AI领跑者","description":"","frontmatter":{},"headers":[],"relativePath":"ai/models/domestic/doubao.md","filePath":"ai/models/domestic/doubao.md"}'),n={name:"ai/models/domestic/doubao.md"};function d(i,t,o,s,h,p){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="豆包学习笔记-从字节内孵化器到全球多模态ai领跑者" tabindex="-1">豆包学习笔记：从字节内孵化器到全球多模态AI领跑者 <a class="header-anchor" href="#豆包学习笔记-从字节内孵化器到全球多模态ai领跑者" aria-label="Permalink to &quot;豆包学习笔记：从字节内孵化器到全球多模态AI领跑者&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>豆包（Doubao）是字节跳动自主研发并推出的通用大语言模型与人工智能产品品牌，底层模型在早期被称为“云雀”，由火山引擎提供技术支撑与商业化平台。作为字节跳动在AI大模型时代最核心的战略产品，豆包承载着这家巨头从“信息分发”向“任务处理”转型的关键使命。</p><p>不同于以技术突破为先导的DeepSeek或GLM，豆包的发展路径鲜明地体现了“产品牵引、场景驱动”的理念——依托字节跳动海量的C端流量、丰富的内容生态和工业级应用场景，豆包从诞生之日起就聚焦于大规模生产环境下的使用需求，走出了一条“模型即服务、服务即产品”的独特道路。从2024年5月首次发布到2026年2月跨入2.0时代，豆包在短短不到两年内实现了从“能用”到“好用”再到“全模态智能”的三级跳，日均Token调用量从2024年5月的约1200亿飙升至2026年3月的120万亿，一年增长1000倍，成为中国大模型市场调用量最大的品牌之一。</p><p>在中文大模型基准测评SuperCLUE中，豆包以71.53分拿下国内第一，正式跻身全球第一梯队，与GPT-5.4仅差0.95分。这一成绩标志着中国大模型已从追赶阶段进入与全球顶尖模型正面竞争的纵深阶段。</p><h2 id="二、发展历程" tabindex="-1">二、发展历程 <a class="header-anchor" href="#二、发展历程" aria-label="Permalink to &quot;二、发展历程&quot;">​</a></h2><h3 id="_2-1-基础奠基期-2023–2024年-从内部孵化到正式发布" tabindex="-1">2.1 基础奠基期（2023–2024年）：从内部孵化到正式发布 <a class="header-anchor" href="#_2-1-基础奠基期-2023–2024年-从内部孵化到正式发布" aria-label="Permalink to &quot;2.1 基础奠基期（2023–2024年）：从内部孵化到正式发布&quot;">​</a></h3><p>豆包的研发根植于字节跳动在AI领域的长期技术积累。字节跳动早在2016年就成立了AI Lab，由前微软亚洲研究院副院长马维英领衔，早于阿里巴巴、百度等互联网巨头在AI基础研究领域的布局。</p><p>2023年8月，豆包底层模型通过《生成式人工智能服务管理暂行办法》备案正式上线，完成了产品化的合规准备。2024年5月15日，在火山引擎原动力大会上，豆包大模型以“云雀”为内部代号正式面向公众发布。彼时的豆包主力模型pro-32k版以低于行业99%的定价加入市场，开启了国内大模型价格战的序幕。同年12月，豆包大模型版本迎来一次重大更新，较5月版本实现综合能力提升32%，推理能力提升13%，数学能力达到GPT-4o水平。</p><p>在落地层面，截至2024年底，豆包已广泛集成至字节系产品矩阵——抖音、剪映、番茄小说等应用中都可直接调用其功能，实现了从模型到产品的“内循环”闭环。</p><h3 id="_2-2-技术爆发期-2025年-多模态矩阵全面铺开" tabindex="-1">2.2 技术爆发期（2025年）：多模态矩阵全面铺开 <a class="header-anchor" href="#_2-2-技术爆发期-2025年-多模态矩阵全面铺开" aria-label="Permalink to &quot;2.2 技术爆发期（2025年）：多模态矩阵全面铺开&quot;">​</a></h3><p>2025年是豆包技术能力全面爆发的关键年份，从1月到12月，豆包以平均每月一至两次的频率持续推新：</p><p><strong>2025年1月</strong>，豆包实时语音大模型上线，支持情感交互与方言理解。同时豆包组建AGI团队“Seed Edge”，标志着字节在通用人工智能方向上的长期布局正式启动。</p><p><strong>2025年2月</strong>，豆包团队发布稀疏模型架构UltraMem，解决了MoE推理的高额访存瓶颈，推理成本最高可降低83%，这项成果被人工智能顶级会议ICLR 2025接收。同月，豆包开源视频生成模型VideoWorld并推出通信优化系统COMET。</p><p><strong>2025年6月</strong>，豆包大模型1.6正式发布，提供最低、低、中、高四种可调节的思考长度，成为国内首个原生支持“分档调节思考长度”的模型，价格较上一代下降63%。同时，视频生成模型Seedance 1.0 pro同期上线。</p><p><strong>2025年10月</strong>，豆包大模型1.6发布升级版本，新增语音合成模型2.0和声音复刻模型2.0。在教育场景中，语音模型对小学至高中阶段全学科的复杂公式朗读准确率可达90%。</p><p><strong>2025年12月</strong>，豆包视频生成模型Seedance 1.8版本发布，火山引擎正式发布豆包大模型1.8。豆包App日活用户突破1亿，成为国内首个日活破亿的独立AI应用。豆包大模型日均Token调用量突破50万亿，半年内增长200%，全球排名仅次于OpenAI和Google。</p><h3 id="_2-3-全模态agent时代-2026年迄今-2-0跨代升级" tabindex="-1">2.3 全模态Agent时代（2026年迄今）：2.0跨代升级 <a class="header-anchor" href="#_2-3-全模态agent时代-2026年迄今-2-0跨代升级" aria-label="Permalink to &quot;2.3 全模态Agent时代（2026年迄今）：2.0跨代升级&quot;">​</a></h3><p>2026年2月14日，正值中国农历春节前夕，火山引擎正式发布豆包大模型2.0（Doubao-Seed-2.0），这是豆包自2024年5月首次发布后的首次跨代升级。2.0包含Pro、Lite、Mini三款通用Agent模型和Code模型，全面覆盖从高复杂度推理到轻量级高频调用的多样化应用场景。在多模态理解、复杂指令执行与长程任务处理能力上实现系统性跃升。</p><p>同期，视频生成模型Seedance 2.0和图像创作模型Seedream 5.0 Lite相继在2月12日和13日正式发布，形成“基础模型+视频生成+图像创作”三大模型联动的全链路布局。Seedance 2.0以“1分钟生成好莱坞级大片”的效果在全球引发轰动，被海外媒体称为“又一个DeepSeek时刻”。</p><p>2026年3月，豆包在中文大模型基准测评SuperCLUE中以71.53分排名国内第一，跻身全球第一梯队。截至同月，豆包日均Token使用量突破120万亿，比2024年5月发布时增长1000倍。</p><p>2026年4月，火山引擎发布新一代汽车AI解决方案，豆包大模型智能汽车搭载量突破700万辆。</p><p>2026年5月6日，豆包大模型家族迎来首款全模态理解模型——Doubao-Seed-2.0-lite，首次实现视频、图像、音频、文本四种模态的原生统一理解，标志着字节跳动在全模态交互领域迈出关键一步。同月，豆包在App Store上线付费订阅服务，推出三档会员体系，探索增值服务模式。</p><h2 id="三、核心技术架构" tabindex="-1">三、核心技术架构 <a class="header-anchor" href="#三、核心技术架构" aria-label="Permalink to &quot;三、核心技术架构&quot;">​</a></h2><h3 id="_3-1-架构演进-从moe到ultramem的创新路径" tabindex="-1">3.1 架构演进：从MoE到UltraMem的创新路径 <a class="header-anchor" href="#_3-1-架构演进-从moe到ultramem的创新路径" aria-label="Permalink to &quot;3.1 架构演进：从MoE到UltraMem的创新路径&quot;">​</a></h3><p>豆包在底层架构上走出了一条清晰且具有差异化的技术曲线——不是简单地追求更大规模的稠密模型，而是持续在稀疏激活架构方向深耕。</p><p>在早期阶段，豆包的底层模型基于Transformer架构，但随着模型规模的扩大，推理成本和访存效率成为最大瓶颈。字节豆包团队在架构层面的转折点是2025年2月提出的UltraMem稀疏模型架构。这项被ICLR 2025接收的创新解决了MoE推理时因batch size和sequence length较小、少量token即可激活几乎所有专家所导致的访存急剧上升和推理延迟大幅增加的问题。</p><p>实验数据显示，在同等计算资源下，训练规模达2000万value的UltraMem模型实现了领先的推理速度和模型性能，推理成本相比MoE架构最高降低83%，推理速度提升2–6倍。这一突破使豆包在保持大模型能力的同时，实现了可商业化的推理成本结构。</p><p>在1.6和2.0版本中，豆包进一步采用了混合专家（MoE）架构，通过动态稀疏激活技术使模型推理时仅激活12%的神经元，计算量减少70%，处理1万字文档的推理成本从0.32元降至0.008元。</p><h3 id="_3-2-分档思考长度调节" tabindex="-1">3.2 分档思考长度调节 <a class="header-anchor" href="#_3-2-分档思考长度调节" aria-label="Permalink to &quot;3.2 分档思考长度调节&quot;">​</a></h3><p>豆包大模型1.6在国内首创原生支持“分档调节思考长度”功能，提供最低、低、中、高四种思考模式。这一设计满足企业在不同场景下对模型效果、时延、成本的不同需求：在低思考长度模式下，相比升级前的单一思考模式，总输出tokens下降77.5%、思考时间下降84.6%，而模型效果保持不变。这一技术细节对豆包的企业级规模化部署具有重要意义——企业可以针对不同任务精细调配推理资源。</p><h3 id="_3-3-多模态能力矩阵" tabindex="-1">3.3 多模态能力矩阵 <a class="header-anchor" href="#_3-3-多模态能力矩阵" aria-label="Permalink to &quot;3.3 多模态能力矩阵&quot;">​</a></h3><p>豆包的多模态能力是其核心技术护城河之一。截至2026年5月，豆包已形成覆盖全模态的完整模型矩阵：</p><p><strong>视觉理解模块</strong>：豆包2.0全面升级了多模态能力，在视觉推理、感知能力、空间推理与长上下文理解等任务中均达到世界顶尖水平，豆包2.0 Pro在大多数相关基准测试中取得最高分。在面对动态场景时，豆包2.0在TVBench等关键测评中处于领先位置，在EgoTempo基准上甚至超过了人类分数，表明其捕捉“变化、动作、节奏”等动态信息的能力已显著超越人类平均感知水平。</p><p>2025年9月，豆包视觉模块新增国风美学引擎，构建了三维国风美学参数空间，可解析《千里江山图》的矿物颜料光谱特征，建立包含12种矿物色相和8种皴法笔触的参数矩阵。在文生图层面，豆包文生图模块日均生成5000万张图片，达到行业领先的生成规模。</p><p><strong>语音理解与交互</strong>：豆包早期便以“语音理解和生成一体化”作为核心竞争力之一。2025年1月上线的实时语音大模型支持情感交互与方言理解，实现了可打断的端到端语音对话。2025年10月发布的语音合成模型2.0通过情感动力学模型将情感分解为“语调基频”“节奏熵值”“共振峰偏移”三个维度，在新闻播报场景中使听众的情感共鸣度提升41%。</p><p>至2026年5月，Doubao-Seed-2.0-lite已支持19种语种的精准语音转写、中英文与其他14个语种的互译，并能深度捕捉语音中的情绪变化、环境背景声与音乐细节。</p><h3 id="_3-4-gui理解与执行一体化" tabindex="-1">3.4 GUI理解与执行一体化 <a class="header-anchor" href="#_3-4-gui理解与执行一体化" aria-label="Permalink to &quot;3.4 GUI理解与执行一体化&quot;">​</a></h3><p>豆包2.0系列在GUI能力上的突破是“端到端Agent”闭环的关键。Doubao-Seed-2.0-lite首次实现了GUI理解与执行的一体化——既能精准识别按钮、菜单、表单、弹窗等界面元素及其状态，也能稳定完成点击、输入、右键、滚动、拖拽等Browser Use与Computer Use操作，真正从“读懂一张网页”到“跨应用、跨窗口连续执行一整套业务流程”。</p><h2 id="四、模型体系全景" tabindex="-1">四、模型体系全景 <a class="header-anchor" href="#四、模型体系全景" aria-label="Permalink to &quot;四、模型体系全景&quot;">​</a></h2><h3 id="_4-1-基础模型系列" tabindex="-1">4.1 基础模型系列 <a class="header-anchor" href="#_4-1-基础模型系列" aria-label="Permalink to &quot;4.1 基础模型系列&quot;">​</a></h3><p>豆包基础模型采用“旗舰+轻量+差异化”的产品矩阵策略，满足从复杂推理到轻量调用的全场景覆盖：</p><table tabindex="0"><thead><tr><th style="text-align:center;">模型版本</th><th style="text-align:left;">定位</th><th style="text-align:left;">核心能力</th><th style="text-align:center;">上下文支持</th><th style="text-align:center;">定价参考</th></tr></thead><tbody><tr><td style="text-align:center;">Doubao-Seed-2.0-Pro</td><td style="text-align:left;">旗舰深度推理与Agent模型</td><td style="text-align:left;">复杂逻辑推理、长链路任务</td><td style="text-align:center;">32K-256K</td><td style="text-align:center;">输入3.2元/百万tokens</td></tr><tr><td style="text-align:center;">Doubao-Seed-2.0-Lite</td><td style="text-align:left;">高性能轻量模型</td><td style="text-align:left;">综合能力超越豆包1.8，兼顾成本与效果</td><td style="text-align:center;">32K-256K</td><td style="text-align:center;">输入0.6元/百万tokens</td></tr><tr><td style="text-align:center;">Doubao-Seed-2.0-Mini</td><td style="text-align:left;">低延迟高并模型</td><td style="text-align:left;">能力媲美1.6Pro版，速度为先</td><td style="text-align:center;">32K-128K</td><td style="text-align:center;">低价</td></tr><tr><td style="text-align:center;">Doubao-Seed-2.0-Code</td><td style="text-align:left;">编程专项模型</td><td style="text-align:left;">大型代码库理解、端到端应用生成</td><td style="text-align:center;">32K-256K</td><td style="text-align:center;">9.9元/月（订阅）</td></tr><tr><td style="text-align:center;">Doubao-Seed-2.0-lite</td><td style="text-align:left;">全模态理解模型</td><td style="text-align:left;">视频+图像+音频+文本原生统一理解</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr></tbody></table><p>豆包2.0 Pro全面对标GPT 5.2与Gemini 3 Pro，在SuperGPQA科学领域评测中分数超越GPT 5.2，在HealthBench上排名第一，在IMO、CMO数学奥赛及ICPC编程竞赛中取得金牌成绩。</p><h3 id="_4-2-视觉与多模态创作模型" tabindex="-1">4.2 视觉与多模态创作模型 <a class="header-anchor" href="#_4-2-视觉与多模态创作模型" aria-label="Permalink to &quot;4.2 视觉与多模态创作模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">模型</th><th style="text-align:left;">定位</th><th style="text-align:left;">核心能力</th></tr></thead><tbody><tr><td style="text-align:center;">Seedance 2.0</td><td style="text-align:left;">视频生成旗舰</td><td style="text-align:left;">支持图像、视频、音频、文本四种模态混合输入，1分钟生成高质量视频，物理真实感领先全球</td></tr><tr><td style="text-align:center;">Seedream 5.0 Lite</td><td style="text-align:left;">图像生成旗舰</td><td style="text-align:left;">统一多模态架构，图文对齐与主体一致性提升，支持实时检索能力</td></tr><tr><td style="text-align:center;">VideoWorld</td><td style="text-align:left;">开源视频生成模型</td><td style="text-align:left;">2025年2月开源，支持视频理解与生成</td></tr></tbody></table><p>Seedance 2.0在2026年2月发布后迅速成为现象级产品，其支持图像、视频、音频、文本四种模态的同时或混合输入，使AI从一个仅能接收文本指令的“猜谜者”进化成为一个能同时理解多种模态的“全能执行导演”。</p><h3 id="_4-3-音频与语音模型" tabindex="-1">4.3 音频与语音模型 <a class="header-anchor" href="#_4-3-音频与语音模型" aria-label="Permalink to &quot;4.3 音频与语音模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">模型</th><th style="text-align:left;">定位</th><th style="text-align:left;">核心能力</th></tr></thead><tbody><tr><td style="text-align:center;">豆包实时语音大模型</td><td style="text-align:left;">实时对话</td><td style="text-align:left;">支持情感交互与方言理解，低延迟、可打断</td></tr><tr><td style="text-align:center;">豆包语音合成模型2.0</td><td style="text-align:left;">TTS生成</td><td style="text-align:left;">复杂公式朗读、情感动态调节</td></tr><tr><td style="text-align:center;">豆包声音复刻模型2.0</td><td style="text-align:left;">音色克隆</td><td style="text-align:left;">支持音色定制</td></tr></tbody></table><p>豆包语音模型家族已覆盖语音合成、语音识别、声音复刻、实时语音、同声传译、音乐创作、播客创作等7大领域，覆盖超过4.6亿台智能终端。</p><h2 id="五、全模态能力突破" tabindex="-1">五、全模态能力突破 <a class="header-anchor" href="#五、全模态能力突破" aria-label="Permalink to &quot;五、全模态能力突破&quot;">​</a></h2><h3 id="_5-1-从-多模态-到-全模态-的三级跃迁" tabindex="-1">5.1 从“多模态”到“全模态”的三级跃迁 <a class="header-anchor" href="#_5-1-从-多模态-到-全模态-的三级跃迁" aria-label="Permalink to &quot;5.1 从“多模态”到“全模态”的三级跃迁&quot;">​</a></h3><p>豆包在全模态领域的发展走了一条清晰的演进路径。2025年2月，UltraMem稀疏架构的发布为后续全模态能力的爆发奠定了算力基础。2025年6月，豆包1.6成为国内首个支持256K上下文的综合思考模型，初步具备跨模态交互能力。</p><p>真正的拐点出现在2026年5月。Doubao-Seed-2.0-lite的发布标志着国内大模型厂商首次推出“全模态”统一理解模型，颠覆了过去“拼接式”多模态的主流做法——视频、图像、音频、文本在模型内部作为统一的输入信号源进行联合推理，模型自主判断何时调用何种模态进行融合，实现了从理解到执行的全流程贯通。</p><h3 id="_5-2-音画同步深度推理" tabindex="-1">5.2 音画同步深度推理 <a class="header-anchor" href="#_5-2-音画同步深度推理" aria-label="Permalink to &quot;5.2 音画同步深度推理&quot;">​</a></h3><p>Doubao-Seed-2.0-lite最重要的突破是首次实现了“音画同步”的深度联合推理。模型不仅能“看懂”视频画面，还能结合背景音频精准判断视听一致性，甚至能根据自然语言指令在长视频中精准定位特定事件发生的时间点，跨越多个时间段提取关键线索，持续追踪人物与事件发展。</p><p>在音频理解基准测试中，该模型在语音识别、翻译等多项任务上超越Gemini-3.1-Pro。在物理HiPhO和医疗MedXpertQA等高阶学科推理任务中，模型在视觉理解维度大幅超越当年2月发布的Doubao-Seed-2.0-pro版本，在细粒度感知BabyVision、WorldVQA与具身理解ERQA等前沿领域达到SOTA水平。</p><h3 id="_5-3-实时视频流分析" tabindex="-1">5.3 实时视频流分析 <a class="header-anchor" href="#_5-3-实时视频流分析" aria-label="Permalink to &quot;5.3 实时视频流分析&quot;">​</a></h3><p>豆包2.0在多模态度量方面重点强化了对时间序列与运动感知的理解。在多个流式实时问答视频基准测试中表现优异，能够作为AI助手完成实时视频流分析、环境感知、主动纠错与情感陪伴，实现从被动问答到主动指导的交互升级，可应用于健身、穿搭等陪伴场景。</p><p>在美术馆等专业场景中，豆包已实现真实落地应用。2026年1月，豆包正式成为上海浦东美术馆两项国际大展的官方AI讲解员，这是AI产品首次以“官方身份”进驻美术馆，能辨识数百件展品并支持连续、深度的追问式互动。</p><h2 id="六、性能评测与行业排名" tabindex="-1">六、性能评测与行业排名 <a class="header-anchor" href="#六、性能评测与行业排名" aria-label="Permalink to &quot;六、性能评测与行业排名&quot;">​</a></h2><h3 id="_6-1-superclue中文大模型基准" tabindex="-1">6.1 SuperCLUE中文大模型基准 <a class="header-anchor" href="#_6-1-superclue中文大模型基准" aria-label="Permalink to &quot;6.1 SuperCLUE中文大模型基准&quot;">​</a></h3><p>2026年3月，SuperCLUE发布中文大模型基准测评结果。在22款国内外主流模型中，字节跳动旗下豆包（Doubao-Seed-2.0-pro）以71.53分排名国内第一，与GPT-5.4仅差0.95分，正式进入全球第一梯队。在智能体任务规划这一高阶能力维度上，豆包的表现超越多款海外模型，跻身全球前五。</p><h3 id="_6-2-多维度核心评测表现" tabindex="-1">6.2 多维度核心评测表现 <a class="header-anchor" href="#_6-2-多维度核心评测表现" aria-label="Permalink to &quot;6.2 多维度核心评测表现&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">评测项</th><th style="text-align:center;">豆包2.0 Pro成绩</th><th style="text-align:left;">对标竞争</th></tr></thead><tbody><tr><td style="text-align:center;">HLE-text（人类的最后考试）</td><td style="text-align:center;">54.2分（最高分）</td><td style="text-align:left;">大幅领先其他模型</td></tr><tr><td style="text-align:center;">SuperGPQA（科学领域评测）</td><td style="text-align:center;">超越GPT 5.2</td><td style="text-align:left;">在HealthBench上排名第一</td></tr><tr><td style="text-align:center;">TVBench / EgoTempo</td><td style="text-align:center;">领先位置 / 超过人类基准</td><td style="text-align:left;">动态场景感知能力行业顶尖</td></tr><tr><td style="text-align:center;">IMO/CMO数学奥赛</td><td style="text-align:center;">金牌成绩</td><td style="text-align:left;">与ICPC编程竞赛同步取得</td></tr><tr><td style="text-align:center;">Putnam数学能力评测</td><td style="text-align:center;">优于对标模型</td><td style="text-align:left;">数学推理能力达到世界顶尖</td></tr><tr><td style="text-align:center;">MMLU</td><td style="text-align:center;">较前代提升18%</td><td style="text-align:left;">在数学推理、代码生成等场景表现突出</td></tr></tbody></table><p>在EgoTempo测评中，豆包2.0得分超过了人类基准，这一测试专门评估模型对“变化、动作、节奏”的感知能力，反映了其在流式视频处理和动态场景理解上的领先性。</p><h3 id="_6-3-视频生成能力" tabindex="-1">6.3 视频生成能力 <a class="header-anchor" href="#_6-3-视频生成能力" aria-label="Permalink to &quot;6.3 视频生成能力&quot;">​</a></h3><p>在2025年末的大模型横评测试中，面对“拉布拉多系着粉白条纹围裙、用爪子拿着铲子在锅里炒菜”的复杂指令，豆包与文心一言、通义万相同列视频生成能力领先梯队，完全满足指令要求。</p><h3 id="_6-4-日均调用量——市场验证的硬指标" tabindex="-1">6.4 日均调用量——市场验证的硬指标 <a class="header-anchor" href="#_6-4-日均调用量——市场验证的硬指标" aria-label="Permalink to &quot;6.4 日均调用量——市场验证的硬指标&quot;">​</a></h3><p>豆包大模型的日均Token使用量走势，直接反映了其市场接受度的爆炸式增长：</p><ul><li><strong>2024年5月</strong>（首次发布）：约1200亿/日</li><li><strong>2025年6月</strong>：约16万亿/日（较发布时增长超100倍）</li><li><strong>2025年9月底</strong>：突破30万亿/日</li><li><strong>2025年12月</strong>：突破50万亿/日，半年内增长200%，全球排名仅次于OpenAI和Google</li><li><strong>2026年3月</strong>：突破120万亿/日，相较发布时增长1000倍</li></ul><h2 id="七、商业模式与定价策略" tabindex="-1">七、商业模式与定价策略 <a class="header-anchor" href="#七、商业模式与定价策略" aria-label="Permalink to &quot;七、商业模式与定价策略&quot;">​</a></h2><h3 id="_7-1-区间定价模式的创新" tabindex="-1">7.1 区间定价模式的创新 <a class="header-anchor" href="#_7-1-区间定价模式的创新" aria-label="Permalink to &quot;7.1 区间定价模式的创新&quot;">​</a></h3><p>豆包在商业化层面的核心创新体现在定价模式上。火山引擎首创了按输入长度区间定价的策略，在0–32K（使用量最大区间）内，豆包1.6的输入价格为0.8元/百万tokens，输出价格8元/百万tokens，在此区间内综合成本相比上一代深度思考模型、DeepSeek R1降低63%。</p><table tabindex="0"><thead><tr><th style="text-align:center;">输入区间</th><th style="text-align:center;">输入价格</th><th style="text-align:center;">输出价格</th></tr></thead><tbody><tr><td style="text-align:center;">0–32K</td><td style="text-align:center;">0.8元/百万tokens</td><td style="text-align:center;">8元/百万tokens</td></tr><tr><td style="text-align:center;">32K–128K</td><td style="text-align:center;">1.2元/百万tokens</td><td style="text-align:center;">16元/百万tokens</td></tr><tr><td style="text-align:center;">128K–256K</td><td style="text-align:center;">2.4元/百万tokens</td><td style="text-align:center;">24元/百万tokens</td></tr></tbody></table><p>这种精细化定价的核心逻辑是火山引擎发现不同上下文的计算消耗存在明显差异，通过PD分离等技术手段对各个区间成本进行定向优化，实现成本与技术红利的释放。</p><h3 id="_7-2-低价普惠策略" tabindex="-1">7.2 低价普惠策略 <a class="header-anchor" href="#_7-2-低价普惠策略" aria-label="Permalink to &quot;7.2 低价普惠策略&quot;">​</a></h3><p>豆包在2024年5月首次发布时，即以主力模型pro-32k版定价低于行业99%的姿态搅动市场。2025年6月1.6版本发布后，价格进一步下调63%。</p><p>在C端，豆包坚持免费模式吸引了海量用户。截至2025年12月，豆包App日活突破1亿，成为国内首个日活破亿的独立AI应用。火山引擎通过“AI节省计划”为企业和开发者进一步节约成本，最高可节省47%的使用费用。</p><h3 id="_7-3-增值服务付费探索" tabindex="-1">7.3 增值服务付费探索 <a class="header-anchor" href="#_7-3-增值服务付费探索" aria-label="Permalink to &quot;7.3 增值服务付费探索&quot;">​</a></h3><p>2026年5月4日，豆包在App Store发布付费订阅声明，新增三档会员选项：标准版连续包月68元（连续包年688元）、加强版连续包月200元（连续包年2048元）、专业版连续包月500元（连续包年5088元）。豆包官方回应称免费服务会继续保留，付费功能主要面向PPT生成、数据分析、影视制作等复杂生产力任务，免费版继续面向日常使用。这是豆包从“全民免费”迈向“价值分级”的关键一步。</p><h3 id="_7-4-b端maas业务与生态" tabindex="-1">7.4 B端MaaS业务与生态 <a class="header-anchor" href="#_7-4-b端maas业务与生态" aria-label="Permalink to &quot;7.4 B端MaaS业务与生态&quot;">​</a></h3><p>在B端，豆包通过火山引擎提供MaaS服务，2025年上半年火山引擎以49.2%的份额占比位居中国公有云大模型服务市场第一。在汽车行业，豆包大模型智能汽车搭载量突破700万辆。火山引擎还推出了面向制造业的HiAgent智能体平台，海亮集团借助豆包大模型仅三个月就完成了620个AI智能体的部署，约相当于传统IT模式至少一年的工作量。</p><h2 id="八、行业应用与c端生态" tabindex="-1">八、行业应用与C端生态 <a class="header-anchor" href="#八、行业应用与c端生态" aria-label="Permalink to &quot;八、行业应用与C端生态&quot;">​</a></h2><h3 id="_8-1-字节跳动的-大模型内循环" tabindex="-1">8.1 字节跳动的“大模型内循环” <a class="header-anchor" href="#_8-1-字节跳动的-大模型内循环" aria-label="Permalink to &quot;8.1 字节跳动的“大模型内循环”&quot;">​</a></h3><p>豆包最大且最独特的竞争优势在于字节跳动强大的产品内循环体系。豆包被深度嵌入抖音、剪映、番茄小说等亿级用户平台，用户可以在一系列高频生活场景中无感使用豆包能力：在抖音中调用视频字幕总结，在剪映中使用脚本创作辅助，在番茄小说中进行AI互动。</p><p>依托Seedream生图模型与Seedance视频生成模型，豆包构建了多模态内容创作能力，“三宫格P图”等轻量化玩法多次登上社交平台热搜，带动了百万级的自然下载量。这种“内循环”使豆包在未付出巨额市场营销成本的情况下实现了破亿DAU——据称是字节跳动历史上市场推广费用最低的破亿DAU产品之一。</p><h3 id="_8-2-系统级ai入口战略" tabindex="-1">8.2 系统级AI入口战略 <a class="header-anchor" href="#_8-2-系统级ai入口战略" aria-label="Permalink to &quot;8.2 系统级AI入口战略&quot;">​</a></h3><p>2025年12月，豆包联合中兴发布nubia M153工程样机，进军AI手机硬件。豆包手机助手可跨应用操作——订机票、点外卖、比价购物等任务不再需要用户在多个App间切换，只需语音指令即可由AI助手自动执行完整操作链路。这一尝试引发了行业关于“流量入口主权”和“数据安全边界”的广泛讨论。</p><h3 id="_8-3-行业垂直解决方案" tabindex="-1">8.3 行业垂直解决方案 <a class="header-anchor" href="#_8-3-行业垂直解决方案" aria-label="Permalink to &quot;8.3 行业垂直解决方案&quot;">​</a></h3><p>在汽车领域，豆包推出Agentic AI架构的汽车AI解决方案，一个AI大脑深度联动整车，打通车控、导航、智驾等关键功能域，实现“感知—推理—执行—记忆—学习”一体化闭环。在汽车行业的搭载量已突破700万辆。</p><p>在智能制造领域，海亮集团借助HiAgent一站式智能体平台和豆包大模型，三个月完成620个AI智能体部署，覆盖制造业供应链全链条。</p><p>在内容创作领域，基于豆包大模型的推文漫自动化生产方案帮助客户月均产能提升3倍；蝉妈妈利用豆包构建了端到端的内容电商服务矩阵，包含Seedream生图、Seedance视频生成、ASR语音识别和TTS合成等多种能力的协同运用。</p><p>在文旅与教育场景，豆包与上海浦东美术馆合作，成为官方AI讲解员，支持数百件展品的辨识与连续追问式互动；教育场景中，2025年10月发布的语音合成模型2.0对小学至高中全学科复杂公式的朗读准确率已达90%。</p><h2 id="九、竞争格局与行业定位" tabindex="-1">九、竞争格局与行业定位 <a class="header-anchor" href="#九、竞争格局与行业定位" aria-label="Permalink to &quot;九、竞争格局与行业定位&quot;">​</a></h2><h3 id="_9-1-与头部模型的横向对比" tabindex="-1">9.1 与头部模型的横向对比 <a class="header-anchor" href="#_9-1-与头部模型的横向对比" aria-label="Permalink to &quot;9.1 与头部模型的横向对比&quot;">​</a></h3><p>豆包的市场地位已可与其他头部模型平视竞争，各模型各有侧重：</p><table tabindex="0"><thead><tr><th style="text-align:center;">维度</th><th style="text-align:center;">豆包</th><th style="text-align:center;">Qwen 2.5</th><th style="text-align:center;">DeepSeek R1</th><th style="text-align:center;">文心5.0</th></tr></thead><tbody><tr><td style="text-align:center;">核心优势</td><td style="text-align:center;">全模态理解、Agent执行、C端生态</td><td style="text-align:center;">多语言覆盖、开源生态</td><td style="text-align:center;">推理深度、数学能力</td><td style="text-align:center;">知识增强、中文理解</td></tr><tr><td style="text-align:center;">SuperCLUE得分</td><td style="text-align:center;">71.53（国内第一）</td><td style="text-align:center;">约70</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">日均Token调用</td><td style="text-align:center;">120万亿</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td style="text-align:center;">C端用户月活</td><td style="text-align:center;">豆包App日活破亿</td><td style="text-align:center;">约2亿</td><td style="text-align:center;">—</td><td style="text-align:center;">4.3亿</td></tr><tr><td style="text-align:center;">多模态定位</td><td style="text-align:center;">全模态原生统一</td><td style="text-align:center;">多模态融合</td><td style="text-align:center;">文本推理领先</td><td style="text-align:center;">多模态理解</td></tr></tbody></table><p>在C端场景中，豆包因其全双工语音实时交互和流畅的多模态体验被用户评价为“一个能随时响应的AI”，综合体验评价领先国内绝大多数AI产品。在视频生成方面，豆包与其他领先模型并列第一梯队。在Agent能力维度，豆包在智能体任务规划上已超越多款海外模型，跻身全球前五。</p><h3 id="_9-2-字节跳动的-满贯-战略" tabindex="-1">9.2 字节跳动的“满贯”战略 <a class="header-anchor" href="#_9-2-字节跳动的-满贯-战略" aria-label="Permalink to &quot;9.2 字节跳动的“满贯”战略&quot;">​</a></h3><p>豆包背后承载的不仅是模型能力本身，更是字节跳动向“AI云原生”转型的宏大战略。2025年，AI Lab整体并入Seed团队，由前谷歌科学家、Gemini核心开发者吴永辉担任负责人，全面推动公司技术架构向AI云原生方向转型。</p><p>2026年春节，火山引擎成为中央广播电视总台春晚独家AI云合作方，豆包参与多种互动玩法——这是字节跳动将AI产品推至国民级高度的标志性事件。在投入层面，字节计划2026年投入1600亿元加码AI，其中约800亿元用于采购AI芯片，相当于其2025年净利润的四分之一。</p><h2 id="十、收费争议-从全民免费到价值分级" tabindex="-1">十、收费争议：从全民免费到价值分级 <a class="header-anchor" href="#十、收费争议-从全民免费到价值分级" aria-label="Permalink to &quot;十、收费争议：从全民免费到价值分级&quot;">​</a></h2><p>2026年5月4日，豆包在App Store发布付费订阅声明的消息引发广泛关注。三档月度会员价格——标准版68元/月、加强版200元/月、专业版500元/月——被外界解读为国产大模型“免费时代结束”的信号。</p><p>但豆包官方的回应揭示了更为复杂的商业逻辑：免费服务会继续保留，增值服务仍在测试阶段，付费功能主要指向PPT生成、数据分析、影视制作等复杂高价值任务，免费版继续面向日常使用。本质上看，豆包并未取消免费模式，而是在免费基本盘之上叠加了“增值服务”选项，通过分级定价来匹配不同用户群体的消费能力和使用深度。</p><p>这一转变反映了国产大模型从“烧钱换规模”向“价值交换”的商业化成熟。正如行业人士评论，“豆包的收费模式，区分的是用户‘聊天’和‘干活’的需求”——聊天免费，但帮你写出完整商业计划书、生成精美PPT、完成数据分析的深度服务，值得付费。</p><h2 id="十一、总结与展望" tabindex="-1">十一、总结与展望 <a class="header-anchor" href="#十一、总结与展望" aria-label="Permalink to &quot;十一、总结与展望&quot;">​</a></h2><h3 id="_11-1-核心竞争力" tabindex="-1">11.1 核心竞争力 <a class="header-anchor" href="#_11-1-核心竞争力" aria-label="Permalink to &quot;11.1 核心竞争力&quot;">​</a></h3><ol><li><p><strong>端到端全模态能力</strong>：豆包走在了行业全模态竞争的最前列。从Doubao-Seed-2.0-lite开始，豆包首次实现了视频、图像、音频、文本四种模态的原生统一理解，而非简单的后期拼接，使AI系统具备了真正意义上的“感知—理解—推理—执行”闭环能力。</p></li><li><p><strong>极致的推理成本效率</strong>：豆包通过MoE动态稀疏激活（推理时仅激活12%的神经元）和UltraMem稀疏模型架构（推理成本最高降83%），将大模型的算力成本降到了接近商业可行性的最低点，为海量规模化部署奠定了基础。</p></li><li><p><strong>字节内循环的生态壁垒</strong>：豆包被嵌入抖音、剪映等亿级产品矩阵，形成了“研发→使用→反馈→迭代”的完整数据飞轮，这种产品层面的生态壁垒是其他独立AI企业无法复制的核心护城河。</p></li><li><p><strong>中国最大规模的大模型商业落地</strong>：日均Token调用量突破120万亿、汽车行业搭载超700万辆、火山引擎以49.2%份额居中国公有云大模型服务市场第一，这些数据共同证明豆包在AI产业化落地方面处于领先地位。</p></li><li><p><strong>早于Meta的战略定力</strong>：字节跳动的AI布局始于2016年，早于国内绝大多数互联网公司近十年。在DeepSeek等开源模型凭借技术领先抢占了部分市场份额的背景下，豆包稳扎稳打，以中国最大规模的算力投资和生态建设构筑了护城河。</p></li></ol><h3 id="_11-2-未来展望" tabindex="-1">11.2 未来展望 <a class="header-anchor" href="#_11-2-未来展望" aria-label="Permalink to &quot;11.2 未来展望&quot;">​</a></h3><p>展望未来，豆包可能沿着以下方向持续演进：</p><ol><li><p><strong>全模态深度融合</strong>：随着Doubao-Seed-2.0-lite的发布，全模态统一理解的架构已初步成形，未来将向更精准的跨模态对齐和实时交互能力延伸。</p></li><li><p><strong>Agent化深化</strong>：从2.0系列的Agent定位到GUI执行闭环的实现，豆包正从“回答问题”全面走向“端到端执行任务”，下一步将是更复杂的多Agent协作和跨场景自主决策。</p></li><li><p><strong>国际化拓展</strong>：基于Seedance 2.0在海外市场的惊艳表现，豆包具备在视频生成和多模态创作等维度与国际巨头直接竞争的潜力。</p></li><li><p><strong>企业级垂直深耕</strong>：在金融、汽车、制造、医疗等领域，豆包将继续深化垂直场景的行业模型定制，把通用大模型变成解决具体问题的专业工具。</p></li><li><p><strong>付费商业化成熟</strong>：从纯免费到“免费+增值”的分级收费将是豆包构建可持续商业模式的核心路径，以高质量、高价值的深度服务吸引高付费意愿的用户和企业客户。</p></li></ol><p>豆包的发展轨迹向外界展示了一个关键信号：中国AI大模型的竞争焦点正从“谁参数更大”转向“谁落地更深、体验更好、成本更低”。豆包凭借全模态能力、极致成本和字节内循环生态的三重优势，在这一新赛道上已占据了领先地位。</p>',113)])])}const x=e(n,[["render",d]]);export{g as __pageData,x as default};
